        if M.attr("Carry") ~= "pc" or typeof(g) ~= "Vector3" or not r then return end
        from = r.Position
        to = Vector3.new(g.X, from.Y, g.Z)
    end
    local walled = (to - from).Magnitude < 1
    F.busy = true
    local T = (to - from).Magnitude / sp
    local ts = os.clock()
    S.task = __T["Running home"]
    local c = RunService.Heartbeat:Connect(function()
        local rr = M.root()
        if not rr or walled then return end
        local a = math.min(1, (os.clock() - ts) / T)
        local q = from:Lerp(to, a)
        rr.CFrame = CFrame.lookAt(q, to)
        rr.AssemblyLinearVelocity = (to - from).Unit * sp
    end)
    while not walled and RUNNING and os.clock() - ts < T + 0.2 and M.attr("Carry") == "pc" and not on("f_pause") do task.wait() end
    c:Disconnect()
    F.busy = false
    if M.attr("Carry") ~= "pc" and not M.attr("Holding") and os.clock() - F.caughtAt > 3 and typeof(M.attr("DroppedAt")) == "Vector3" and tier > 0 then
        F.tierSpeed[tier] = math.max(15, sp * 0.85)
        LOG("slower for tier", tier, math.floor(F.tierSpeed[tier]))
    end
    local t0 = os.clock()
    while RUNNING and os.clock() - t0 < 4 and M.attr("Carry") == "pc" do task.wait(0.1) end
end
function F.toBase()
    if M.attr("Carry") == "pc" or F.paused() then return end
    local P = F.plot()
    local r = M.root()
    if not P or not r then return end
    local cf, size = P:GetBoundingBox()
    local lp2 = cf:PointToObjectSpace(r.Position)
    if math.abs(lp2.X) < size.X / 2 - 4 and math.abs(lp2.Z) < size.Z / 2 - 4 and os.clock() - (F.baseErr or 0) > 3 then return end
    S.task = __T["Going to base"]
    M.tp(cf.Position + Vector3.new(0, 6, 0))
    F.baseErr = 0
    task.wait(0.6)
end
F.badSpot = {}
function F.placeErr(text)
    local t = text:lower()
    if t:find("in the way") then F.lastErr = "way" F.lastErrAt = os.clock()
    elseif t:find("too far") then F.lastErr = "far" F.lastErrAt = os.clock()
    elseif t:find("outside your base") then F.lastErr = "out" F.lastErrAt = os.clock() end
end
function F.place()
    if F.full() or M.attr("Carry") == "pc" or F.paused() then return false end
    F.toBase()
    local Lay = D.Lay
    local pi = tonumber(M.attr("PlotIndex"))
    if not Lay or not pi then return false end
    local ok, cf = pcall(Lay.plotCF, pi)
    if not ok or typeof(cf) ~= "CFrame" then return false end
    local tries = 0
    for pass = 1, 2 do
        local r = M.root()
        if not r then return false end
        local me = cf:PointToObjectSpace(r.Position)
        local cand = {}
        local occ = {}
        local P = F.plot()
        local items = P and P:FindFirstChild("Items")
        if items then for _, it in ipairs(items:GetChildren()) do local okp, pv = pcall(function() return it:GetPivot().Position end) if okp and not it.Name:find("^Minion") then local l = cf:PointToObjectSpace(pv) local sz = it:IsA("Model") and select(2, it:GetBoundingBox()) or it.Size occ[#occ + 1] = { X = l.X, Z = l.Z, h = math.max(sz.X, sz.Z) / 2 } end end end
        for x = -25, 25, 5 do
            for z = -25, 25, 5 do
                local key = x .. "," .. z
                local d = math.sqrt((x - me.X) ^ 2 + (z - me.Z) ^ 2)
                local free = true
                for _, o in ipairs(occ) do if math.abs(o.X - x) < o.h + 3.2 and math.abs(o.Z - z) < o.h + 3.2 then free = false break end end
                if free and not (F.badSpot[key] and os.clock() < F.badSpot[key]) and Lay.onFloor(x, z) then cand[#cand + 1] = { x, z, d, key } end
            end
        end
        table.sort(cand, function(a, b) return a[3] < b[3] end)
        if #cand == 0 and pass == 2 then F.noRoomUntil = os.clock() + 45 LOG("floor full") return false end
        for _, sp in ipairs(cand) do
            local uid = M.attr("Holding")
            if not uid then return true end
            if F.paused() or tries >= 24 then return false end
            tries += 1
            if sp[3] > 18 then M.tp(cf * Vector3.new(sp[1] * 0.8, 5, sp[2] * 0.8)) task.wait(0.4) end
            S.task = __T["Placing package"]
            F.lastErr = nil
            task.wait(math.max(0, 0.18 - (os.clock() - (F.lastPlaceAt or 0))))
            F.lastPlaceAt = os.clock()
            M.fire("PlaceAt", uid, sp[1], sp[2], 0)
            local t0 = os.clock()
            while os.clock() - t0 < 0.6 and M.attr("Holding") and not F.lastErr do task.wait(0.05) end
            if not M.attr("Holding") then return true end
            if F.lastErr == "way" or F.lastErr == "out" then F.badSpot[sp[4]] = os.clock() + (F.lastErr == "out" and 9e9 or 120)
            elseif F.lastErr == "far" then break end
        end
        if not M.attr("Holding") then return true end
        S.task = __T["Going to base"]
        M.tp(cf.Position + Vector3.new(0, 5, 0))
        task.wait(0.6)
    end
    return M.attr("Holding") == nil
end
function F.openAll()
    local P = F.plot()
    local items = P and P:FindFirstChild("Items")
    if not items then return 0 end
    local n = 0
    for _, pk in ipairs(items:GetChildren()) do
        local tries = F.openTries[pk] or 0
        if pk.Name:find("^Package") and pk:GetAttribute("Ready") and os.clock() >= tries and not F.paused() then
            local pp = pk:FindFirstChildWhichIsA("ProximityPrompt", true)
            if pp and pp.Enabled and pp.ActionText:upper():find("OPEN") then
                F.openTries[pk] = os.clock() + 20
                S.task = __T["Opening packages"]
                F.fireP(pp)
                task.wait(0.6)
                n += 1
                S.opens += 1
            end
        end
    end
    return n
end
function F.recover()
    local dpos = M.attr("DroppedAt")
    if typeof(dpos) ~= "Vector3" then return false end
    local best, bd
    for _, m in ipairs(Workspace:GetChildren()) do
        if m.Name == "LoosePackage" and m:IsA("Model") then
            local p = F.wp(m)
            local d = p and (p - dpos).Magnitude
            if d and d < 20 and (not bd or d < bd) then best, bd = m, d end
        end
    end
    local pp = best and best:FindFirstChildWhichIsA("ProximityPrompt", true)
    if not pp or not pp.Enabled or (F.looseCd[best] and os.clock() < F.looseCd[best]) then return false end
    F.looseCd[best] = os.clock() + 30
    S.task = __T["Recovering dropped package"]
    F.fireP(pp)
    local t0 = os.clock()
    while os.clock() - t0 < 2 and M.attr("Carry") ~= "pc" do task.wait(0.1) end
    if M.attr("Carry") ~= "pc" then return false end
    F.glideHome()
    local t1 = os.clock()
    while os.clock() - t1 < 6 and not M.attr("Holding") do task.wait(0.2) end
    if M.attr("Holding") then
        F.place()
        S.recovers = (S.recovers or 0) + 1
        S.steals += 1
        S.fails = math.max(0, S.fails - 1)
        LOG("recovered", math.floor(bd))
        return true
    end
    return false
end
function F.looseSafe(m, hidx)
    if not hidx then return true end
    local p = F.wp(m)
    if not p then return false end
    local door
    for _, h in ipairs(F.houses()) do if h.idx == hidx then door = F.wp(h.door) break end end
    if not door then return true end
    local zw = F.wallLine(p)
    local toWall = zw and math.abs(math.abs(p.Z) - math.abs(zw)) or 999
    local carry = math.clamp(val("s_carry", 55), 20, 58)
    return toWall / carry + 0.4 < (door - p).Magnitude / 110
end
function F.loose()
    local r = M.root()
    if not r then return false end
    local mine = M.attr("DroppedAt")
    local best, bd
    for _, m in ipairs(Workspace:GetChildren()) do
        if m.Name == "LoosePackage" and m:IsA("Model") then
            local pp = m:FindFirstChildWhichIsA("ProximityPrompt", true)
            local tier = tonumber(m:GetAttribute("Tier")) or 1
            local hidx = tonumber(m:GetAttribute("House"))
            local zone = hidx and D.Lay and D.Lay.zoneOf and select(2, pcall(D.Lay.zoneOf, hidx))
            local cfg = F.cfg(tonumber(zone) or tier)
            local ok = pp and pp.Enabled and pp.ActionText:upper():find("STEAL") and not (F.looseCd[m] and os.clock() < F.looseCd[m]) and F.looseSafe(m, hidx)
            if ok and cfg and not F.reach(cfg) then ok = false end
            if ok then
                local d = (F.wp(m) - r.Position).Magnitude
                if not best or tier > best.tier or (tier == best.tier and d < bd) then best, bd = { m = m, pp = pp, tier = tier }, d end
            end
        end
    end
    if not best then return false end
    S.task = __T["Grabbing a loose package"]
    F.looseCd[best.m] = os.clock() + 30
    F.fireP(best.pp)
    local t0 = os.clock()
    while os.clock() - t0 < 2 and M.attr("Carry") ~= "pc" do task.wait(0.1) end
    if M.attr("Carry") == "pc" then
        F.glideHome()
        local t1 = os.clock()
        while os.clock() - t1 < 6 and not M.attr("Holding") do task.wait(0.2) end
        if M.attr("Holding") then
            F.place()
            S.steals += 1
            LOG("loose grabbed", best.tier)
            return true
        end
        S.fails += 1
        LOG("loose lost", best.tier)
    end
    return false
end
function F.steal(h)
    S.task = __T["Knocking: "] .. tostring(h.pp.ObjectText)
    local dp = F.wp(h.door)
    M.tp(dp + h.door.CFrame.LookVector * 4 + Vector3.new(0, 2, 0))
    task.wait(0.3)
    if typeof(fireproximityprompt) == "function" then pcall(fireproximityprompt, h.pp) end
    local t0 = os.clock()
    while os.clock() - t0 < 6 and M.attr("RunState") ~= "door" do task.wait(0.1) end
    if M.attr("RunState") ~= "door" then F.refused[h.idx] = os.clock() + 20 return false end
    S.task = __T["Scaring"]
    local sp
    t0 = os.clock()
    while os.clock() - t0 < 8 and not sp and M.attr("RunState") == "door" do sp = F.prompt(h.m, "SCARE") task.wait(0.15) end
    if F.paused() then return false end
    if sp then F.fireP(sp) else M.fire("Prank") end
    t0 = os.clock()
    while os.clock() - t0 < 4 and M.attr("RunState") == "door" do task.wait(0.1) end
    if M.attr("RunState") ~= "shock" then
        S.fails += 1
        LOG("scare failed", h.zone)
        F.refused[h.idx] = os.clock() + 30
        return false
    end
    task.wait(0.55)
    S.task = __T["Stealing"]
    local r = M.root()
    local stl
    t0 = os.clock()
    while os.clock() - t0 < 4 and not stl do stl = F.prompt(h.m, "STEAL", 40, r and r.Position or dp) or (os.clock() - t0 > 1 and F.prompt(Workspace.World, "STEAL", 30, dp)) task.wait(0.15) end
    if stl then F.fireP(stl) end
    t0 = os.clock()
    while os.clock() - t0 < 2.5 and M.attr("Carry") ~= "pc" do task.wait(0.1) end
    if M.attr("Carry") ~= "pc" then LOG("steal missed", h.zone) return false end
    F.glideHome()
    local t1 = os.clock()
    while os.clock() - t1 < 6 and not M.attr("Holding") do task.wait(0.2) end
    if not M.attr("Holding") then
        S.fails += 1
        LOG("caught or dropped", h.zone)
        return false
    end
    F.place()
    S.steals += 1
    F.sinceTrain += 1
    LOG("stole", h.zone, tostring(h.pp.ObjectText))
    return true
end
function F.station(kind, secs)
    local P = F.plot()
    local st = P and P:FindFirstChild(kind == "tread" and "Treadmill" or "Trainer")
    local pad = st and st:FindFirstChild("Pad")
    if not pad or not M.attr("TrainingUnlocked") then F.trainBad = os.clock() + 60 return false end
    S.task = kind == "tread" and __T["Training speed"] or __T["Training scare"]
    local r = M.root()
    if r and (r.Position - pad.Position).Magnitude < 5 then M.tp(pad.Position + Vector3.new(10, 3.2, 0)) task.wait(2.2) end
    M.tp(pad.Position + Vector3.new(0, 3.2, 0))
    local t0 = os.clock()
    while RUNNING and os.clock() - t0 < 2.5 and not M.attr("Station") do task.wait(0.25) end
    if not M.attr("Station") then F.trainBad = os.clock() + 60 return false end
    while RUNNING and os.clock() - t0 < secs and not on("f_pause") and M.attr("Carry") ~= "pc" do task.wait(0.5) end
    F.sinceTrain = 0
    M.tp(pad.Position + Vector3.new(10, 3.2, 0))
    return true
end
function F.trainNext()
    local mode = val("s_trainMode", "Both")
    if mode == "Scare" then return "trainer" end
    if mode == "Speed" then return "tread" end
    F.trainFlip = ((F.trainFlip or 0) + 1) % 3
    if F.trainFlip == 0 then return "tread" end
    local nextH
    for _, h in ipairs(F.houses()) do
        if h.cfg and (not nextH or h.zone < nextH.zone) and F.chance(h.cfg) < val("s_min", 80) and h.zone > 0 then nextH = h end
    end
    if not nextH then return "trainer" end
    if F.chance(nextH.cfg) < val("s_min", 80) then return "trainer" end
    return "tread"
end
F.signs = {
    { key = "tread", cfg = "Treadmill", lvl = "TreadLevel" },
    { key = "trainer", cfg = "Trainer", lvl = "TrainerLevel" },
    { key = "minions", cfg = "Minions", lvl = "MinionLevel" },
    { key = "base", cfg = "Base", lvl = "BaseLevel" },
}
function F.num(v)
    if type(v) == "number" then return v end
    local t = tostring(v or ""):gsub("[%s,$]", ""):upper()
    local n, suf = t:match("^([%d%.]+)(%a*)$")
    n = tonumber(n)
    if not n then return 0 end
    local mul = { K = 1e3, M = 1e6, B = 1e9, T = 1e12, QA = 1e15, QI = 1e18 }
    return n * (mul[suf] or 1)
end
function F.upgrades()
    if not M.attr("TrainingUnlocked") and M.cash() >= (tonumber(D.C.TrainingUnlockPrice) or 500) then M.fire("SignBuy", "unlock") task.wait(0.4) end
    local best, bp
    local keep = F.num(val("s_keep", "0"))
    for _, s in ipairs(F.signs) do
        local c = D.C[s.cfg]
        local lv = tonumber(M.attr(s.lvl, 1)) or 1
        local price = c and c.prices and c.prices[lv]
        if price and M.cash() - keep >= price and (not bp or price < bp) then best, bp = s, price end
    end
    if not best then return false end
    local lv0 = M.attr(best.lvl)
    M.fire("SignBuy", best.key)
    task.wait(0.6)
    if M.attr(best.lvl) ~= lv0 then S.buys += 1 LOG("upgrade", best.key, bp) return true end
    return false
end
function F.sellWorst()
    local P = F.plot()
    local items = P and P:FindFirstChild("Items")
    if not items then return false end
    local worst, wd
    for _, it in ipairs(items:GetChildren()) do
        local dps = tonumber(it:GetAttribute("Dps"))
        if it.Name:find("^Item_") and dps and not it:GetAttribute("Insane") and (not wd or dps < wd) then worst, wd = it, dps end
    end
    local h = F.pick()
    local tier = worst and (tonumber(worst:GetAttribute("Tier")) or 1) or 99
    if not worst or not h or tier >= h.zone then return false end
    local uid = tonumber(worst.Name:match("(%d+)$"))
    if not uid then return false end
    S.task = __T["Selling worst item"]
    local s0 = M.attr("SlotsUsed")
    M.fire("Unequip", uid)
    task.wait(0.8)
    local stall = Workspace.World:FindFirstChild("Stalls") and Workspace.World.Stalls:FindFirstChild("Sell")
    if stall then M.tp(stall:GetPivot().Position + Vector3.new(0, 3, 6)) task.wait(0.6) end
    local got = false
    local inv = D.N:FindFirstChild("Inventory")
    local cn = inv and inv.OnClientEvent:Connect(function() got = true end)
    M.fire("SellItem", uid)
    local t0 = os.clock()
    while os.clock() - t0 < 1.5 and not got do task.wait(0.1) end
    if cn then cn:Disconnect() end
    if got then S.sold = (S.sold or 0) + 1 LOG("sold", uid, wd) return true end
    LOG("sell failed", uid)
    return false
end
function F.claims()
    M.fire("ClaimDaily")
    local cells = D.C.Gifts and D.C.Gifts.cells
    local n = type(cells) == "table" and #cells or 12
    local mask = tostring(M.attr("GiftMask", ""))
    local zero = tonumber(M.attr("GiftZero"))
    local now = Workspace:GetServerTimeNow()
    for i = 1, n do
        local okA, at = pcall(function() return D.C.cellAt and D.C.cellAt(i) end)
        at = okA and tonumber(at)
        local due = not (zero and at) or zero + at <= now
        if mask:sub(i, i) ~= "1" and due and not F.paused() then M.fire("ClaimGift", i) task.wait(0.55) end
    end
    M.fire("ClaimIndexTier", 1)
    M.fire("ClaimMutIndex")
    M.fire("OfflineClaim")
    M.fire("ClaimAllIndex")
    if not M.attr("JoinClaimed") and not F.joinTried then
        F.joinTried = true
        M.fire("JoinStep", "favorite")
        task.wait(0.6)
        M.fire("JoinStep", "group")
        task.wait(0.6)
        M.fire("JoinClaim")
    end
end
