    local CG = Tab:AddRightGroupbox(__T["Changelog"], "list")
    CG:AddLabel('<font color="#f5c542"><b>2026-11-20  v1.0</b></font>', true)
    local groups = {
        { __T["Farm"], { __T["+ Auto steal (instant knock, scare, steal)"], __T["+ Best zone by scare chance or pick a zone"], __T["+ Safe route home over the walls"], __T["+ Live zone list (stealing, below min, locked)"], __T["+ Recover dropped package"], __T["+ Auto open packages + skip reveal"], __T["+ Grab loose + night packages"] } },
        { "Base", { __T["+ Auto train scare, speed or both"], __T["+ Keep cash for upgrades"], __T["+ Auto upgrades"], __T["+ Auto sell worst when full"], __T["+ Auto equip best items + pets"], __T["+ Auto fuse pets into shiny"], __T["+ Auto claim rewards"] } },
        { "Player", { __T["+ House, player + package ESP"], __T["+ Anti knockback (bat, ragdoll, freeze)"], __T["+ Speed"], __T["+ Anti AFK"] } },
        { __T["Other"], { __T["+ Streamer mode"] } },
    }
    for _, g in ipairs(groups) do
        CG:AddLabel('<b>' .. g[1] .. '</b>', true)
        for _, l in ipairs(g[2]) do CG:AddLabel(l, true) end
